<?php
namespace Modules\Ran\Services;use DomainException;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Sale,SaleLine,StockLot};use Modules\Ran\Integrations\{CustomerIntegrationService,FinanceIntegrationService};use Modules\Ran\Support\RanContext;
class SaleService{public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private CustomerIntegrationService $customers,private FinanceIntegrationService $finance,private AuditService $audit){}
 public function create(array $d):Sale{return DB::transaction(function()use($d){$contact=$this->customers->contactDetails(!empty($d['customer_contact_id'])?(int)$d['customer_contact_id']:null);$subtotal=0;$making=0;$prepared=[];foreach($d['lines'] as $line){$lot=StockLot::query()->with('item')->findOrFail($line['stock_lot_id']);$qty=(float)$line['quantity'];$unit=(float)$line['unit_price'];$total=$qty*$unit+(float)($line['making_charge']??0)+(float)($line['other_charge']??0)+(float)($line['tax_amount']??0)-(float)($line['discount_amount']??0);$subtotal+=$qty*$unit;$making+=(float)($line['making_charge']??0);$prepared[]=[$lot,$line,$total];}$total=$subtotal+$making+collect($d['lines'])->sum(fn($l)=>(float)($l['other_charge']??0)+(float)($l['tax_amount']??0)-(float)($l['discount_amount']??0))-(float)($d['discount_amount']??0)+(float)($d['tax_amount']??0)+(float)($d['rounding_amount']??0);$s=Sale::create(array_merge(RanContext::scope(['location_id'=>(int)($d['location_id']??RanContext::locationId()),'store_id'=>(int)($d['store_id']??RanContext::storeId())]),['invoice_no'=>$this->numbers->next('sale'),'invoice_date'=>$d['invoice_date'],'customer_contact_id'=>$d['customer_contact_id']??null,'customer_name'=>$contact['name']??$d['customer_name']??null,'customer_mobile'=>$contact['mobile']??$d['customer_mobile']??null,'customer_email'=>$contact['email']??$d['customer_email']??null,'status'=>'draft','subtotal'=>$subtotal,'making_charge_total'=>$making,'discount_amount'=>(float)($d['discount_amount']??0),'tax_amount'=>(float)($d['tax_amount']??0),'rounding_amount'=>(float)($d['rounding_amount']??0),'total_amount'=>$total,'paid_amount'=>0,'balance_amount'=>$total,'notes'=>$d['notes']??null,'terms'=>$d['terms']??null]));foreach($prepared as [$lot,$line,$lineTotal])SaleLine::create(array_merge(RanContext::scope(['location_id'=>$s->location_id,'store_id'=>$s->store_id]),$line,['sale_id'=>$s->id,'item_id'=>$lot->item_id,'description'=>$line['description']??$lot->item?->name,'line_total'=>$lineTotal,'cost_amount'=>(float)$lot->unit_cost*(float)$line['quantity']]));$this->audit->record('sale_created',$s);return $s->load('lines');});}
 public function post(Sale $s):Sale{return DB::transaction(function()use($s){$s=Sale::query()->lockForUpdate()->with('lines.stockLot')->findOrFail($s->id);if($s->status==='posted')return $s;if($s->status!=='draft')throw new DomainException('Only draft sales can be posted.');foreach($s->lines as $l){if(!$l->stockLot)throw new DomainException('A sale line has no stock lot.');$this->inventory->issue($l->stockLot,(float)$l->quantity,(float)$l->net_weight,['reference_type'=>'sale','reference_id'=>$s->id,'reference_no'=>$s->invoice_no,'description'=>'Ran sale']);}$this->finance->postSale($s);if($s->customer_contact_id)$this->customers->debit((int)$s->customer_contact_id,(float)$s->total_amount,(string)$s->invoice_date,"Ran Invoice {$s->invoice_no}");$s->update(['status'=>'posted','posted_by'=>RanContext::userId(),'posted_at'=>now()]);$this->audit->record('sale_posted',$s);return $s;});}}
